public class SignupFormValidatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static SignupFormValidator panel;

    static String text(String name) {
        java.awt.Component c = find(panel, name);
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    static void fill(String name, String value) {
        java.awt.Component c = find(panel, name);
        if (c instanceof javax.swing.JTextField) {
            ((javax.swing.JTextField) c).setText(value);
        }
    }

    public static void main(String[] args) {
        try {
            panel = new SignupFormValidator();
            boolean ok = panel.validateForm();
            check("blank form is rejected", false, ok);
            check("blank name message", "Name is required", text("nameError"));
            check("blank email message", "Email is required", text("emailError"));
            check("blank form summary", "3 problems", text("summary"));

            fill("nameField", "  Ada  ");
            fill("emailField", "ada@example.com");
            fill("ageField", "31");
            check("good form is accepted", true, panel.validateForm());
            check("no name error left", "", text("nameError"));
            check("good form summary", "Ready to submit", text("summary"));

            fill("emailField", "ada.example.com");
            panel.validateForm();
            check("email without an at sign", "Email is invalid", text("emailError"));
            check("single problem is singular", "1 problem", text("summary"));

            fill("emailField", "ada@example.com");
            fill("ageField", "twelve");
            panel.validateForm();
            check("non numeric age", "Age must be a number", text("ageError"));

            fill("ageField", "12");
            panel.validateForm();
            check("age below the range", "Age must be 13-120", text("ageError"));

            fill("ageField", "13");
            fill("nameField", "A");
            panel.validateForm();
            check("13 is allowed", "", text("ageError"));
            check("one letter name is too short", "Name is too short", text("nameError"));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

