import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;

public class SignupFormValidator extends JPanel {

    private final JTextField nameField = new JTextField(12);
    private final JTextField emailField = new JTextField(12);
    private final JTextField ageField = new JTextField(4);
    private final JLabel nameError = new JLabel("");
    private final JLabel emailError = new JLabel("");
    private final JLabel ageError = new JLabel("");
    private final JLabel summary = new JLabel("(not checked)");

    public SignupFormValidator() {
        nameField.setName("nameField");
        emailField.setName("emailField");
        ageField.setName("ageField");
        nameError.setName("nameError");
        emailError.setName("emailError");
        ageError.setName("ageError");
        summary.setName("summary");
        add(nameField);
        add(nameError);
        add(emailField);
        add(emailError);
        add(ageField);
        add(ageError);
        add(summary);
    }

    public boolean validateForm() {
        String name = nameField.getText().trim();
        if (name.isEmpty()) {
            nameError.setText("Name is required");
        } else if (name.length() < 2) {
            nameError.setText("Name is too short");
        } else {
            nameError.setText("");
        }

        String email = emailField.getText().trim();
        int at = email.indexOf('@');
        if (email.isEmpty()) {
            emailError.setText("Email is required");
        } else if (at <= 0 || email.indexOf('.', at) < 0) {
            emailError.setText("Email is invalid");
        } else {
            emailError.setText("");
        }

        String age = ageField.getText().trim();
        if (age.isEmpty()) {
            ageError.setText("Age is required");
        } else {
            try {
                int years = Integer.parseInt(age);
                if (years < 13 || years > 120) {
                    ageError.setText("Age must be 13-120");
                } else {
                    ageError.setText("");
                }
            } catch (NumberFormatException ex) {
                ageError.setText("Age must be a number");
            }
        }

        int problems = 0;
        if (!nameError.getText().isEmpty()) {
            problems++;
        }
        if (!emailError.getText().isEmpty()) {
            problems++;
        }
        if (!ageError.getText().isEmpty()) {
            problems++;
        }
        if (problems == 0) {
            summary.setText("Ready to submit");
        } else if (problems == 1) {
            summary.setText("1 problem");
        } else {
            summary.setText(problems + " problems");
        }
        return problems == 0;
    }
}
